iness.\ \par{ f\#\#\# Vicuna}: \hbox to11.38pt{\vbox to7.97pt{\pgfpicture% \makeatletter\hbox{	hinspace\lower 0.0pt\hbox to0.0pt{\pgfsys@beginscope% \pgfsys@invoke{ }\definecolor[named]{pgfstrokecolor}{rgb}{0,0,0}% \pgfsys@color@gray@stroke{0}\pgfsys@invoke{ }\pgfsys@color@gray@fill{0}% \pgfsys@invoke{ }\pgfsys@setlinewidth{	he\pgflinewidth}\pgfsys@invoke{ }% 
